    fps = set()
    incomplete = False
    for rr in view["ruleResults"]:
        if rr["enumeration"]["state"] == "incomplete":
            incomplete = True
    for occ in view["occurrences"]:
        f = occ["finding"]
        if f["correspondence"]["state"] == "matched" and f["fingerprint"]:
            fps.add(f["fingerprint"])
    return fps, incomplete


