            "snapshotId": current_view["snapshotId"],
            "policyDigest": bctx["policyDigest"],
            "scopeDigest": bctx["scopeDigest"],
            "waiverSetDigest": bctx["waiverSetDigest"],
            "detector": "baseline",
        },
        "E1": {
            "snapshotId": current_view["snapshotId"],
            "policyDigest": bctx["policyDigest"],
            "scopeDigest": bctx["scopeDigest"],
            "waiverSetDigest": bctx["waiverSetDigest"],
            "detector": "current",
        },
        "E2": {
            "snapshotId": current_view["snapshotId"],
            "policyDigest": current_view["plan"]["policyDigest"],
            "scopeDigest": bctx["scopeDigest"],
            "waiverSetDigest": bctx["waiverSetDigest"],
            "detector": "current",
